import {APPROVAL_STAGES,approvalRoles,APPROVAL_ROLES,canPerformApproval,canApprove,canProductApprove,canEdit,execute,TERMS,orderTotal,orderStatus,financials,paymentSchedule,flagsFor,shipmentTotals,proportionalSlices,toMinor,toRate,convertMinor,previewImport,major,currentApprovedPrice,priceVarianceForLine} from '../shared/domain.mjs';
import {previewTrackingImport,previewRateImport,rateVariance,freightTrendFor,shippingDocReadiness} from '../shared/shipping.mjs';
const TODAY='2026-09-11';

test('admin bulk deletion retains financials, evidence, snapshots and original serials; restoration resumes the same order',()=>{
 const f=fixture(),a=f.draft(),b=f.draft();f.issue(a);f.commercial(a);f.pay(a);const original=structuredClone(f.state),numbers=[f.get(a).serialNumber,f.get(b).serialNumber],finance=financials(f.state,f.get(a));
 f.run('DELETE_ORDERS',{orderIds:[a,b],remarks:'Remove test orders'},f.role('ADMIN'));
 assert.ok(f.get(a).deletedAt&&f.get(b).deletedAt);assert.deepEqual(financials(f.state,f.get(a)),finance);assert.deepEqual(f.state.payments,original.payments);assert.deepEqual(f.state.files,original.files);assert.deepEqual(f.get(a).revisions,original.orders.find(o=>o.id===a).revisions);assert.deepEqual(f.state.events.slice(0,original.events.length),original.events);
 assert.deepEqual([f.get(a).serialNumber,f.get(b).serialNumber],numbers);assert.equal(canEdit(f.role('ADMIN'),f.get(a)),false);
 for(const type of ['ADD_NOTE','APPROVE_PI','AUTHORIZE_PAYMENT'])assert.throws(()=>f.run(type,{orderId:a,remarks:'Blocked'},f.role('ADMIN')),/deleted/i);
 assert.throws(()=>f.run('VOID_PAYMENT',{paymentId:f.state.payments[0].id,remarks:'Blocked'},f.role('ADMIN')),/deleted/i);
 const c=f.draft({serialNumber:1});assert.ok(f.get(c).serialNumber>Math.max(...numbers));
 f.run('RESTORE_ORDERS',{orderIds:[a,b],remarks:'Resume tests'},f.role('ADMIN'));assert.equal(f.get(a).deletedAt,undefined);assert.equal(f.get(a).serialNumber,numbers[0]);assert.deepEqual(financials(f.state,f.get(a)),finance);f.run('ADD_NOTE',{orderId:a,remarks:'Restored order can resume'});
});

test('bulk delete/restore enforces admin, bounded selection, reason and atomic validation',()=>{
 const f=fixture(),a=f.draft(),b=f.draft(),before=structuredClone(f.state),admin=f.role('ADMIN');
 for(const role of ['MANAGER','EXECUTIVE','PRODUCT_MANAGER','VIEWER'])for(const type of ['DELETE_ORDERS','RESTORE_ORDERS'])assert.throws(()=>f.run(type,{orderIds:[a],remarks:'Attempt'},f.role(role)),e=>e.code==='FORBIDDEN');
 for(const payload of [{orderIds:[],remarks:'x'},{orderIds:[a,a],remarks:'x'},{orderIds:[a,'missing'],remarks:'x'},{orderIds:[a],remarks:''},{orderIds:Array(201).fill(a),remarks:'x'}])assert.throws(()=>f.run('DELETE_ORDERS',payload,admin));
 assert.deepEqual(f.state,before);f.run('DELETE_ORDERS',{orderIds:[a],remarks:'Test'},admin);const deleted=structuredClone(f.state);assert.throws(()=>f.run('DELETE_ORDERS',{orderIds:[b,a],remarks:'Mixed'},admin));assert.throws(()=>f.run('RESTORE_ORDERS',{orderIds:[a,b],remarks:'Mixed'},admin));assert.deepEqual(f.state,deleted);
 const ref=f.get(a).number;assert.throws(()=>f.draft({number:ref}),/already exists/i);
});

test('approval roles remain authoritative with no date-based executive delegation',()=>{
 const f=fixture(),u=f.role('EXECUTIVE');for(const [command,role] of Object.entries(APPROVAL_ROLES)){for(const now of ['2026-09-12T10:00:00Z','2026-09-30T18:29:59Z','2026-10-01T00:00:00Z'])assert.equal(canPerformApproval(u,command,'LAE_IMPORT',now),false);assert.equal(canPerformApproval(f.role(role),command),true);assert.equal(canPerformApproval(f.role('ADMIN'),command),true);assert.equal(canPerformApproval(f.role('VIEWER'),command),false);assert.equal(canPerformApproval({...f.role(role),scopes:[]},command),false);}
 const oid=f.draft();f.run('SUBMIT_ORDER',{orderId:oid});for(const type of Object.keys(APPROVAL_ROLES))assert.throws(()=>execute(f.state,{type,payload:{orderId:oid,now:'2026-09-12T10:00:00Z',user:{role:'ADMIN'}}},u,{now:'2026-09-12T10:00:00Z'}),e=>e.code==='FORBIDDEN',type);
 f.run('APPROVE_ORDER',{orderId:oid});assert.ok(f.state.events.filter(e=>e.action==='PO_APPROVED').every(e=>!e.approvalPolicy));
});

test('multiple response attachments share one confirmation and preserve each document',()=>{
 const f=fixture(),oid=f.draft();f.issue(oid);const ids=[f.file([oid]),f.file([oid])];
 f.run('CONFIRM_SUPPLIER',{orderId:oid,channel:'EMAIL',remarks:'Two supplier responses for one acknowledgement.',fileIds:ids});
 assert.deepEqual(f.get(oid).confirmation.fileIds,ids);assert.equal(f.get(oid).confirmation.fileId,ids[0]);
 assert.deepEqual(f.get(oid).documents.filter(d=>d.type==='SUPPLIER_CONFIRMATION').map(d=>d.fileId),ids);
 const piFiles=[f.file([oid]),f.file([oid])];f.run('RECORD_PI',{orderId:oid,number:'MULTI-PI',date:TODAY,currency:'USD',amount:major(orderTotal(f.get(oid))),quantity:100,termsConfirmed:true,commitmentConfirmed:true,fileIds:piFiles});
 assert.deepEqual(f.get(oid).pi.fileIds,piFiles);assert.equal(f.get(oid).pi.status,'RECEIVED');
 const docs=[f.file([oid]),f.file([oid])];f.run('ATTACH_DOCUMENT',{orderId:oid,type:'OTHER',fileIds:docs});
 assert.deepEqual(f.get(oid).documents.filter(d=>d.type==='OTHER').map(d=>d.fileId),docs);
 assert.deepEqual(f.state.events.at(-1).newValue.fileIds,docs);
});

test('every attachment is validated before workflow mutation; single-file clients still work',()=>{
 const f=fixture(),oid=f.draft();f.issue(oid);const valid=f.file([oid]),wrongOrder=f.file([]),wrongScope=f.file([oid]);f.state.files.find(x=>x.id===wrongScope).scope='UTILITY_DOMESTIC';
 for(const bad of [wrongOrder,wrongScope,'missing'])rejects(f,'CONFIRM_SUPPLIER',{orderId:oid,channel:'EMAIL',remarks:'Invalid second attachment',fileIds:[valid,bad]},/evidence|order/i);
 rejects(f,'CONFIRM_SUPPLIER',{orderId:oid,channel:'EMAIL',remarks:'No files',fileIds:[]},/evidence/i);
 f.run('CONFIRM_SUPPLIER',{orderId:oid,channel:'EMAIL',remarks:'Legacy single file',fileId:valid});assert.equal(f.get(oid).confirmation.fileId,valid);
});

test('all remittance proofs must link to every allocation and receipt files stay grouped',()=>{
 const f=fixture(),oid=f.draft();f.issue(oid);f.commercial(oid);f.run('AUTHORIZE_PAYMENT',{orderId:oid,termIndex:0,shipmentId:null});
 const amount=major(paymentSchedule(f.state,f.get(oid))[0].amount),good=f.file([oid]),bad=f.file([]);
 const p={reference:'MULTI-PAY',date:TODAY,currency:'USD',amount,inrRate:'85',fileIds:[good,bad],allocations:[{orderId:oid,termIndex:0,shipmentId:null,amount,invoiceRate:'1'}]};
 rejects(f,'RECORD_PAYMENT',p,/every allocated order/);
 const second=f.file([oid]);p.fileIds=[good,second];const id=f.run('RECORD_PAYMENT',p).id,payment=f.state.payments.find(p=>p.id===id);assert.deepEqual(payment.fileIds,[good,second]);
 const proofs=[f.file([oid]),f.file([oid])];f.run('ACKNOWLEDGE_PAYMENT',{paymentId:id,allocationId:payment.allocations[0].id,realizedAmount:amount,supplierRate:'1',remarks:'Supplier proof bundle',fileIds:proofs});assert.deepEqual(f.state.payments.find(p=>p.id===id).allocations[0].ackFileIds,proofs);
});

test('optional QC and brand artwork retain multiple files without changing approval gates',()=>{
 const f=fixture(),oid=f.draft();f.issue(oid);f.produce(oid);
 // Optional sample evidence is represented by an empty collection when no files are chosen.
 const other=f.draft();f.issue(other);f.commercial(other);f.pay(other);f.run('RECORD_PREPRODUCTION_SAMPLE',{orderId:other,remarks:'Sample without optional evidence',fileIds:[]});assert.equal(f.get(other).preproductionSample.fileId,null);
 const ids=[f.file([]),f.file([])];f.run('SUBMIT_BRAND_ARTWORK',{itemId:f.item.id,remarks:'Two packaging views',fileIds:ids});const art=f.state.items.find(i=>i.id===f.item.id).artworkRevisions.at(-1);assert.deepEqual(art.fileIds,ids);assert.equal(art.status,'PENDING');
});
function fixture(nowDay=TODAY){let state=createSeed(TODAY),serial=0;state={...state,orders:[],payments:[],files:[],events:[],costs:[],imports:[],revision:0};const role=r=>state.users.find(u=>u.role===r),run=(type,payload,user=role('MANAGER'),day=nowDay)=>{const x=execute(state,{type,payload},user,{now:day+'T10:00:00.000Z',id:()=>`test-${++serial}`});state=x.state;return x.result;},file=(ids=[])=>{const id='file-'+(++serial);state.files.push({id,name:'test-evidence.txt',orderIds:ids,scope:'LAE_IMPORT',mime:'text/plain',size:4});return id;};const item=state.items.find(i=>i.code==='GJPW12'),base=state.bases.find(b=>b.id===item.baseId);const get=id=>state.orders.find(o=>o.id===id);
 const draft=(extra={})=>run('CREATE_ORDER',{number:'TEST-'+(++serial),vendorId:base.vendorId,buyerId:role('EXECUTIVE').id,currency:'USD',paymentTerms:TERMS[0],productionDays:30,productionOverrideReason:'Supplier order commitment.',planningTat:60,routeId:state.routes[0].id,requestedPortDate:'2026-10-25',lines:[{itemId:item.id,quantity:100,unitPrice:'100.00',specId:base.specifications[0].id}],...extra}).id;
 const issue=id=>{run('SUBMIT_ORDER',{orderId:id});run('APPROVE_ORDER',{orderId:id});};
 const confirm=id=>run('CONFIRM_SUPPLIER',{orderId:id,channel:'EMAIL',remarks:'Supplier accepted this version.',fileId:file([id])});
 const pi=id=>{if(get(id).confirmation?.revision!==get(id).revision)confirm(id);run('RECORD_PI',{orderId:id,number:'PI-'+(++serial),date:TODAY,currency:get(id).currency,amount:major(orderTotal(get(id))),quantity:shipmentTotals(get(id)).required,termsConfirmed:true,commitmentConfirmed:true,fileId:file([id])});run('VERIFY_PI',{orderId:id});run('APPROVE_PI',{orderId:id});};
 const technical=id=>run('CONFIRM_TECHNICAL',{orderId:id,channel:'EMAIL',remarks:'Supplier confirmed current technical package.',fileId:file([id])});
 const artwork=id=>{run('SUBMIT_ARTWORK',{orderId:id,fileId:file([id]),remarks:'Brand artwork supplied.'});run('APPROVE_ARTWORK',{orderId:id},role('PRODUCT_MANAGER'));run('CONFIRM_ARTWORK',{orderId:id,fileId:file([id]),remarks:'Artwork accepted.'});};
 const commercial=id=>{pi(id);technical(id);artwork(id);};
 const pay=(id,index=0,sid=null)=>{run('AUTHORIZE_PAYMENT',{orderId:id,termIndex:index,shipmentId:sid});const m=paymentSchedule(state,get(id)).find(m=>m.index===index&&m.shipmentId===sid),amount=major(m.amount);return run('RECORD_PAYMENT',{reference:'TX-'+(++serial),date:TODAY,currency:get(id).currency,amount,inrRate:'85.50',fileId:file([id]),allocations:[{orderId:id,termIndex:index,shipmentId:sid,amount,invoiceRate:'1'}]}).id;};
 const completeSample=id=>run('RECORD_PREPRODUCTION_SAMPLE',{orderId:id,remarks:'Supplier completed pre-production sample.',fileId:file([id])});
 const approveSample=id=>{if(!get(id).preproductionSample||get(id).preproductionSample.status==='REJECTED')completeSample(id);return run('APPROVE_PREPRODUCTION_SAMPLE',{orderId:id,result:'APPROVED',remarks:'Purchase approved pre-production sample.'});};
 const produce=id=>{commercial(id);for(const [i,m]of get(id).paymentTerms.steps.entries())if(m.trigger==='PI')pay(id,i);approveSample(id);run('START_PRODUCTION',{orderId:id,date:TODAY,remarks:'Production start acknowledged.'});run('RECORD_BULK_QC',{orderId:id,result:'PASS',remarks:'Bulk-production QC passed.',fileId:file([id])});run('COMPLETE_PRODUCTION',{orderId:id,date:TODAY,remarks:'Inspection-ready batch.'});};
 const shipment=(id,quantity=100)=>run('ADD_SHIPMENT',{orderId:id,number:'SHP-'+(++serial),containerType:'40HC',origin:'NINGBO',destination:'CHENNAI',rateRouteKey:'NINGBO|CHENNAI|1X40HC',etd:TODAY,eta:'2026-09-30',lines:[{lineId:get(id).lines[0].id,quantity}]}).id;
 const bookRelease=(id,sid,freight='3800')=>{run('BOOK_CONTAINER',{orderId:id,shipmentId:sid,forwarderId:state.vendors.find(v=>v.kind==='LOGISTICS'&&v.status==='ACTIVE').id,forwarderRef:'REF-'+(++serial),date:TODAY,freightUsd:freight,rateRouteKey:'NINGBO|CHENNAI|1X40HC',remarks:'Booking confirmed.'});run('RELEASE_CONTAINER',{orderId:id,shipmentId:sid,container:'TEST'+String(++serial).padStart(7,'0'),date:TODAY,remarks:'Container released for loading.'});};
 const ready=(id,sid)=>{const s=get(id).shipments.find(s=>s.id===sid);if(s.bookingStatus==='PLANNED')bookRelease(id,sid);for(const t of ['COMMERCIAL_INVOICE','PACKING_LIST'])run('ATTACH_DOCUMENT',{orderId:id,shipmentId:sid,type:t,fileId:file([id])});for(const m of paymentSchedule(state,get(id)).filter(m=>m.trigger==='SHIPMENT'&&m.shipmentId===sid))pay(id,m.index,sid);};
 const dispatch=(id,sid,day=TODAY)=>run('DISPATCH_SHIPMENT',{orderId:id,shipmentId:sid,date:day,vessel:'TEST VESSEL',voyage:'V001',location:'NINGBO',remarks:'Loaded on vessel.'});
 const postVessel=(id,sid,day=TODAY)=>{run('RECORD_BL',{orderId:id,shipmentId:sid,number:'FINAL-'+(++serial),date:day,fileId:file([id]),remarks:'Final BL verified.'});run('RECORD_INSURANCE',{orderId:id,shipmentId:sid,masterPolicy:'MASTER-TEST',declarationNumber:'INS-'+(++serial),insuredValue:major(orderTotal(get(id))),currency:get(id).currency,date:day,remarks:'Shipment insured after final BL.',fileId:file([id])});};
 return {get state(){return state;},set state(x){state=x;},role,run,file,item,base,get,draft,issue,confirm,pi,technical,artwork,commercial,pay,completeSample,approveSample,produce,shipment,bookRelease,ready,dispatch,postVessel};}
function rejects(f,type,payload,pattern,user){const before=structuredClone(f.state);assert.throws(()=>f.run(type,payload,user),pattern);assert.deepEqual(f.state,before,'failed command must leave the caller state unchanged');}

test('source seed: 153 untouched raw items, six mapped brand SKUs, eight illustrative orders',()=>{const s=createSeed(TODAY);assert.equal(s.items.filter(i=>i.source==='User-supplied demo item master').length,153);assert.equal(s.items.filter(i=>i.baseId).length,6);assert.equal(s.categories.length,22);assert.equal(s.orders.length,8);assert.ok(s.orders.some(o=>orderStatus(o)==='PORT_ARRIVED'&&financials(s,o).balance>0));});
test('money and FX math use bounded integer minor units',()=>{assert.equal(toMinor('123.45'),12345);assert.throws(()=>toMinor('1.234'));assert.throws(()=>toMinor('-3'));assert.equal(convertMinor(10000,toRate('7.1')),71000);assert.equal(convertMinor(101,toRate('1.5')),152);});
test('pro-rata shipment allocations preserve the exact total down to the cent',()=>{assert.deepEqual(proportionalSlices(100,[1,1,1]),[33,34,33]);for(let n=1;n<1000;n++)assert.equal(proportionalSlices(n,[13,19,21,3]).reduce((a,b)=>a+b,0),n);});
